120: package main
121: 
122: import (
123: 	"context"
124: 	"errors"
125: 	"fmt"
126: )
127: 
128: type Executor func(task *Task) (result string, newTasks []*Task, err error)
129: 
130: func RunPlanLoop(plan *Plan, execute Executor, replanner Replanner, ctrl *LoopController) (*Plan, error) {
131: 	if plan.MaxRounds <= 0 {
132: 		plan.MaxRounds = 15
133: 	}
134: 
135: 	for plan.Round < plan.MaxRounds {
136: 		if err := ctrl.Wait(context.Background()); err != nil {
137: 			return plan, err
138: 		}
139: 		if plan.IsAllDone() {
140: 			return plan, nil
141: 		}
142: 
143: 		task := plan.GetNextPendingTask()
144: 		if task == nil {
145: 			return plan, errors.New("keine ausführbaren Tasks mehr")
146: 		}
147: 
148: 		plan.Round++
149: 		fmt.Printf("\n=== Runde %d | Task %q (%s) ===\n",
150: 			plan.Round, task.ID, task.Description)
151: 
152: 		task.State = InProgress
153: 		result, newTasks, err := execute(task)
154: 
155: 		if err != nil {
156: 			task.State = Failed
157: 			task.Error = err.Error()
158: 		} else {
159: 			task.State = Completed
160: 			task.Result = result
161: 		}
162: 		task.Attempts++
163: 
164: 		for _, nt := range newTasks {
165: 			plan.AddTask(nt)
166: 		}
167: 
168: 		if err := replanner.Update(plan, task); err != nil {
169: 			return plan, err
170: 		}
171: 	}
172: 
173: 	return plan, errors.New("MaxRounds erreicht, Plan nicht vollständig abgeschlossen")
174: }
