178: package main
179: 
180: import "fmt"
181: 
182: type Replanner interface {
183: 	Update(plan *Plan, last *Task) error
184: }
185: 
186: type DefaultReplanner struct {
187: 	OnSuccess func(plan *Plan, t *Task) []*Task
188: }
189: 
190: func (r *DefaultReplanner) Update(plan *Plan, last *Task) error {
191: 	switch last.State {
192: 	case Failed:
193: 		if last.Attempts < last.MaxAttempts {
194: 			last.Attempts++
195: 			last.State = Pending
196: 			last.Error = ""
197: 			fmt.Printf("↻ Replan: Task %q wird erneut versucht (%d/%d)\n",
198: 				last.ID, last.Attempts, last.MaxAttempts)
199: 		} else {
200: 			fmt.Printf("✗ Replan: Task %q endgültig fehlgeschlagen\n", last.ID)
201: 		}
202: 	case Completed:
203: 		if r.OnSuccess != nil {
204: 			for _, nt := range r.OnSuccess(plan, last) {
205: 				plan.AddTask(nt)
206: 				fmt.Printf("+ Replan: Neue Task %q hinzugefügt\n", nt.ID)
207: 			}
208: 		}
209: 	}
210: 	return nil
211: }
