251: import (
252: 	"context"
253: 	"sync"
254: )
255: 
256: type LoopController struct {
257: 	mu       sync.Mutex
258: 	paused   bool
259: 	resumeCh chan struct{}
260: 	stopCh   chan struct{}
261: 	stopped  bool
262: }
263: 
264: func NewLoopController() *LoopController {
265: 	return &LoopController{stopCh: make(chan struct{})}
266: }
267: 
268: func (c *LoopController) Pause() {
269: 	c.mu.Lock()
270: 	defer c.mu.Unlock()
271: 	if c.paused || c.stopped {
272: 		return
273: 	}
274: 	c.paused = true
275: 	c.resumeCh = make(chan struct{})
276: }
277: 
278: func (c *LoopController) Resume() {
279: 	c.mu.Lock()
280: 	defer c.mu.Unlock()
281: 	if !c.paused {
282: 		return
283: 	}
284: 	c.paused = false
285: 	close(c.resumeCh)
286: }
287: 
288: func (c *LoopController) Stop() {
289: 	c.mu.Lock()
290: 	defer c.mu.Unlock()
291: 	if c.stopped {
292: 		return
293: 	}
294: 	c.stopped = true
295: 	if c.paused {
296: 		c.paused = false
297: 		close(c.resumeCh)
298: 	}
299: 	close(c.stopCh)
300: }
301: 
302: func (c *LoopController) IsPaused() bool {
303: 	c.mu.Lock()
304: 	defer c.mu.Unlock()
305: 	return c.paused
306: }
307: 
308: func (c *LoopController) Wait(ctx context.Context) error {
309: 	c.mu.Lock()
310: 	paused, ch, stopped, stopCh := c.paused, c.resumeCh, c.stopped, c.stopCh
311: 	c.mu.Unlock()
312: 
313: 	if stopped {
314: 		return context.Canceled
315: 	}
316: 	if !paused {
317: 		select {
318: 		case <-stopCh:
319: 			return context.Canceled
320: 		case <-ctx.Done():
321: 			return ctx.Err()
322: 		default:
323: 			return nil
324: 		}
325: 	}
326: 	select {
327: 	case <-ch:
328: 		return nil
329: 	case <-stopCh:
330: 		return context.Canceled
331: 	case <-ctx.Done():
332: 		return ctx.Err()
333: 	}
334: }
