654: func (s *WebServer) handleAction(w http.ResponseWriter, r *http.Request) {
655: 	if r.Method != http.MethodPost {
656: 		http.Error(w, "method not allowed", 405)
657: 		return
658: 	}
659: 	var req struct{ Action string `json:"action"` }
660: 	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
661: 		http.Error(w, "bad json", 400)
662: 		return
663: 	}
664: 
665: 	switch req.Action {
666: 	case "run":
667: 		s.mu.Lock()
668: 		if s.running || s.activePlan == nil {
669: 			s.mu.Unlock()
670: 			http.Error(w, "cannot run", 409)
671: 			return
672: 		}
673: 		s.running = true
674: 		s.ctrl = NewLoopController()
675: 		s.runningGoal = s.activePlan.Goal
676: 		s.runningID = s.activeID
677: 		s.loopStarted = true
678: 		plan := s.activePlan
679: 		id := s.activeID
680: 		ctrl := s.ctrl
681: 		s.saveSessionLocked()
682: 		s.mu.Unlock()
683: 		go s.runLoop(plan, id, ctrl)
684: 
685: 	case "pause":
686: 		s.mu.Lock()
687: 		if s.ctrl != nil {
688: 			s.ctrl.Pause()
689: 			s.saveSessionLocked()
690: 		}
691: 		goal := s.runningGoal
692: 		s.mu.Unlock()
693: 		s.broadcast(WSMessage{Type: "state", Msg: "paused", Goal: goal})
694: 
695: 	case "resume":
696: 		s.mu.Lock()
697: 		if s.ctrl == nil {
698: 			s.mu.Unlock()
699: 			http.Error(w, "nothing to resume", 409)
700: 			return
701: 		}
702: 		if s.runningID != "" && s.runningID != s.activeID {
703: 			if p, err := LoadPlanByID(s.runningID); err == nil {
704: 				s.activePlan = p
705: 				s.activeID = s.runningID
706: 				s.broadcast(WSMessage{Type: "plan_loaded", PlanID: s.runningID})
707: 			}
708: 		}
709: 		s.ctrl.Resume()
710: 		if s.running && !s.ctrl.IsPaused() && !s.loopStarted {
711: 			plan := s.activePlan
712: 			id := s.runningID
713: 			ctrl := s.ctrl
714: 			s.loopStarted = true
715: 			s.saveSessionLocked()
716: 			s.mu.Unlock()
717: 			go s.runLoop(plan, id, ctrl)
718: 			s.broadcast(WSMessage{Type: "state", Msg: "running"})
719: 			return
720: 		}
721: 		s.saveSessionLocked()
722: 		s.mu.Unlock()
723: 		s.broadcast(WSMessage{Type: "state", Msg: "running"})
724: 
725: 	case "stop":
726: 		s.mu.Lock()
727: 		if s.ctrl != nil {
728: 			s.ctrl.Stop()
729: 			s.runningID = ""
730: 			s.runningGoal = ""
731: 			s.saveSessionLocked()
732: 		}
733: 		s.mu.Unlock()
734: 
735: 	default:
736: 		http.Error(w, "unknown action", 400)
737: 		return
738: 	}
739: 	w.WriteHeader(202)
740: }
