742: func (s *WebServer) runLoop(plan *Plan, id string, ctrl *LoopController) {
743: 	defer func() {
744: 		s.mu.Lock()
745: 		s.running = false
746: 		s.ctrl = nil
747: 		s.runningID = ""
748: 		s.runningGoal = ""
749: 		s.loopStarted = false
750: 		s.saveSessionLocked()
751: 		s.mu.Unlock()
752: 		_ = SavePlanAs(id, plan)
753: 	}()
754: 
755: 	exec := func(t *Task) (string, []*Task, error) {
756: 		s.broadcast(WSMessage{Type: "task_start", Task: t})
757: 		res, nts, err := s.jimmy.execute(t)
758: 		s.broadcast(WSMessage{Type: "task_done", Task: t, Msg: res})
759: 		return res, nts, err
760: 	}
761: 
762: 	if _, err := RunPlanLoop(plan, exec, &DefaultReplanner{}, ctrl); err != nil {
763: 		s.broadcast(WSMessage{Type: "loop_error", Msg: err.Error()})
764: 	} else {
765: 		s.broadcast(WSMessage{Type: "loop_done"})
766: 	}
767: }
