769: func (s *WebServer) handleWS(w http.ResponseWriter, r *http.Request) {
770: 	c, err := websocket.Accept(w, r, &websocket.AcceptOptions{InsecureSkipVerify: true})
771: 	if err != nil {
772: 		return
773: 	}
774: 	ctx, cancel := context.WithCancel(r.Context())
775: 	s.clientsMu.Lock()
776: 	s.clients[c] = cancel
777: 	s.clientsMu.Unlock()
778: 	defer func() {
779: 		s.clientsMu.Lock()
780: 		delete(s.clients, c)
781: 		s.clientsMu.Unlock()
782: 		cancel()
783: 		c.Close(websocket.StatusNormalClosure, "")
784: 	}()
785: 
786: 	s.mu.Lock()
787: 	init, _ := json.Marshal(map[string]any{
788: 		"type":    "init",
789: 		"plan":    s.activePlan,
790: 		"plan_id": s.activeID,
791: 		"running": s.running,
792: 		"paused":  s.running && s.ctrl != nil && s.ctrl.IsPaused(),
793: 	})
794: 	s.mu.Unlock()
795: 	_ = c.Write(ctx, websocket.MessageText, init)
796: 
797: 	for {
798: 		_, data, err := c.Read(ctx)
799: 		if err != nil {
800: 			return
801: 		}
802: 		var cmd struct{ Cmd string `json:"cmd"` }
803: 		if json.Unmarshal(data, &cmd) == nil && cmd.Cmd != "" {
804: 			go s.handleWSCmd(cmd.Cmd)
805: 		}
806: 	}
807: }
808: 
809: func (s *WebServer) handleWSCmd(cmd string) {
810: 	switch cmd {
811: 	case "pause":
812: 		s.mu.Lock()
813: 		if s.ctrl != nil {
814: 			s.ctrl.Pause()
815: 			s.saveSessionLocked()
816: 		}
817: 		goal := s.runningGoal
818: 		s.mu.Unlock()
819: 		s.broadcast(WSMessage{Type: "state", Msg: "paused", Goal: goal})
820: 	case "resume":
821: 		s.mu.Lock()
822: 		if s.ctrl != nil {
823: 			s.ctrl.Resume()
824: 			if s.running && !s.ctrl.IsPaused() && !s.loopStarted {
825: 				plan := s.activePlan
826: 				id := s.runningID
827: 				ctrl := s.ctrl
828: 				s.loopStarted = true
829: 				s.saveSessionLocked()
830: 				s.mu.Unlock()
831: 				go s.runLoop(plan, id, ctrl)
832: 				s.broadcast(WSMessage{Type: "state", Msg: "running"})
833: 				return
834: 			}
835: 			s.saveSessionLocked()
836: 		}
837: 		s.mu.Unlock()
838: 		s.broadcast(WSMessage{Type: "state", Msg: "running"})
839: 	case "stop":
840: 		s.mu.Lock()
841: 		if s.ctrl != nil {
842: 			s.ctrl.Stop()
843: 			s.runningID = ""
844: 			s.runningGoal = ""
845: 			s.saveSessionLocked()
846: 		}
847: 		s.mu.Unlock()
848: 	case "ping":
849: 		s.broadcast(WSMessage{Type: "pong"})
850: 	}
851: }
852: 
853: func (s *WebServer) broadcast(msg WSMessage) {
854: 	data, _ := json.Marshal(msg)
855: 	s.clientsMu.Lock()
856: 	defer s.clientsMu.Unlock()
857: 	for conn := range s.clients {
858: 		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
859: 		_ = conn.Write(ctx, websocket.MessageText, data)
860: 		cancel()
861: 	}
862: }
