1114: <script>
1115: const $=id=>document.getElementById(id);
1116: const taskList=$('task-list'),logEl=$('log'),planList=$('plan-list');
1117: const planBtn=$('plan-btn'),runBtn=$('run-btn'),pauseBtn=$('pause-btn'),resumeBtn=$('resume-btn'),stopBtn=$('stop-btn');
1118: const statusDot=$('status-dot'),statusText=$('status-text');
1119: let currentPlan=null,running=false,ws=null;
1120: 
1121: function setStatus(text,mode){statusText.textContent=text;statusDot.className='dot '+(mode||'')}
1122: function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
1123: function appendLog(text,cls){
1124:   const time=new Date().toLocaleTimeString('de-DE');
1125:   const line=document.createElement('div');
1126:   line.className='line '+(cls||'');
1127:   line.innerHTML=`<span class="time">${time}</span>${escapeHtml(text)}`;
1128:   logEl.appendChild(line);logEl.scrollTop=logEl.scrollHeight;
1129: }
1130: function stateName(n){return ['Pending','InProgress','Completed','Failed'][n]||'Unknown'}
1131: function updateButtons({running,paused}){
1132:   runBtn.disabled=!!running;
1133:   pauseBtn.disabled=!running||!!paused;
1134:   resumeBtn.disabled=!paused;
1135:   stopBtn.disabled=!running;
1136: }
1137: 
1138: function renderPlan(plan){
1139:   currentPlan=plan;taskList.innerHTML='';
1140:   if(!plan||!plan.tasks||plan.tasks.length===0){
1141:     taskList.innerHTML='<div class="empty">Noch kein Plan.</div>';return;
1142:   }
1143:   for(const t of plan.tasks){
1144:     const state=stateName(t.state);
1145:     const div=document.createElement('div');
1146:     div.className='task '+state;
1147:     div.innerHTML=`
1148:       <span class="badge">${state}</span>
1149:       <div class="desc">
1150:         <div><strong>${escapeHtml(t.id)}</strong> · ${escapeHtml(t.description)}</div>
1151:         ${t.result?`<div class="result">→ ${escapeHtml(t.result)}</div>`:''}
1152:         ${t.error?`<div class="result" style="color:var(--err)">⚠ ${escapeHtml(t.error)}</div>`:''}
1153:       </div>`;
1154:     taskList.appendChild(div);
1155:   }
1156: }
1157: 
1158: async function refreshPlan(){
1159:   try{
1160:     const res=await fetch('/api/plans');
1161:     const data=await res.json();
1162:     if(data.active){
1163:       const r2=await fetch('/api/plan/'+data.active);
1164:       const p=await r2.json();
1165:       if(p.plan)renderPlan(p.plan);
1166:     }
1167:   }catch{}
1168: }
1169: 
1170: async function loadPlans(){
1171:   try{
1172:     const res=await fetch('/api/plans');
1173:     const data=await res.json();
1174:     planList.innerHTML='';
1175:     if(!data.plans||!data.plans.length){planList.innerHTML='<div class="empty">Noch keine Pläne.</div>';return}
1176:     for(const p of data.plans){
1177:       const active=p.id===data.active;
1178:       const div=document.createElement('div');
1179:       div.className='plan-item'+(active?' active':'');
1180:       div.innerHTML=`
1181:         <div style="flex:1;min-width:0">
1182:           <div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><strong>${escapeHtml(p.goal)}</strong></div>
1183:           <div style="font-size:11px;color:var(--muted)">${p.done_count}/${p.task_count} Tasks · ${new Date(p.updated_at).toLocaleString('de-DE')}</div>
1184:         </div>
1185:         <button class="secondary" data-act="load">Laden</button>
1186:         <button class="secondary" data-act="del">✕</button>`;
1187:       div.querySelector('[data-act=load]').onclick=async()=>{
1188:         const r=await fetch('/api/plan/'+p.id);
1189:         const d=await r.json();
1190:         if(d.plan)renderPlan(d.plan);
1191:         if(d.paused){appendLog('⏸ Laufender Loop pausiert.', 'event-replan');setStatus('Pausiert','');updateButtons({running:true,paused:true})}
1192:         loadPlans();
1193:       };
1194:       div.querySelector('[data-act=del]').onclick=async()=>{
1195:         if(!confirm('Plan löschen?'))return;
1196:         await fetch('/api/plan/'+p.id,{method:'DELETE'});
1197:         loadPlans();
1198:       };
1199:       planList.appendChild(div);
1200:     }
1201:   }catch{}
1202: }
1203: 
1204: async function createPlan(){
1205:   const goal=$('goal-input').value.trim();
1206:   if(!goal)return alert('Bitte ein Ziel eingeben.');
1207:   planBtn.disabled=true;setStatus('Plane…','running');
1208:   appendLog(`Plane Ziel: ${goal}`,'event-replan');
1209:   try{
1210:     const res=await fetch('/api/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal})});
1211:     if(!res.ok)throw new Error(await res.text());
1212:     const data=await res.json();
1213:     renderPlan(data.plan);
1214:     runBtn.disabled=false;
1215:     appendLog(`✓ Plan mit ${data.plan.tasks.length} Tasks erstellt.`,'event-done');
1216:     setStatus('Bereit','online');
1217:     if(data.paused){appendLog('⏸ Laufender Loop wurde pausiert.','event-replan');updateButtons({running:true,paused:true})}
1218:     loadPlans();
1219:   }catch(e){
1220:     appendLog('Fehler beim Planen: '+e.message,'event-error');
1221:     setStatus('Fehler','');
1222:   }finally{planBtn.disabled=false}
1223: }
1224: 
1225: async function doAction(action){
1226:   try{
1227:     const res=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});
1228:     if(!res.ok&&res.status!==202)throw new Error(await res.text());
1229:   }catch(e){appendLog('Fehler: '+e.message,'event-error')}
1230: }
1231: 
1232: function connectWS(){
1233:   const proto=location.protocol==='https:'?'wss':'ws';
1234:   ws=new WebSocket(`${proto}://${location.host}/ws`);
1235:   ws.onmessage=ev=>{try{handleEvent(JSON.parse(ev.data))}catch{}};
1236:   ws.onclose=()=>{setStatus('Getrennt','');setTimeout(connectWS,1500)};
1237:   ws.onopen=()=>setStatus('Verbunden','online');
1238: }
1239: 
1240: function handleEvent(ev){
1241:   switch(ev.type){
1242:     case 'init':
1243:       if(ev.plan)renderPlan(ev.plan);
1244:       running=ev.running;
1245:       if(ev.paused){
1246:         appendLog('⏸ Pausierter Loop wiederhergestellt. Resume zum Fortsetzen.','event-replan');
1247:         setStatus('Pausiert','');updateButtons({running:true,paused:true});
1248:       }else if(ev.running){
1249:         setStatus('Läuft…','running');updateButtons({running:true,paused:false});
1250:       }else{
1251:         setStatus('Bereit','online');updateButtons({running:false});
1252:       }
1253:       break;
1254:     case 'task_start':
1255:       appendLog(`▶ Task ${ev.task.id}: ${ev.task.description}`,'event-start');
1256:       refreshPlan();break;
1257:     case 'task_done':
1258:       appendLog(`✓ Task ${ev.task.id} abgeschlossen.`,'event-done');
1259:       refreshPlan();break;
1260:     case 'loop_done':
1261:       appendLog('✓ Loop abgeschlossen.','event-done');
1262:       setStatus('Fertig','online');running=false;updateButtons({running:false});
1263:       refreshPlan();loadPlans();break;
1264:     case 'loop_error':
1265:       appendLog('⚠ '+ev.msg,'event-error');
1266:       setStatus('Fehler','');running=false;updateButtons({running:false});break;
1267:     case 'state':
1268:       if(ev.msg==='paused'){appendLog(`⏸ Pausiert${ev.goal?': '+ev.goal:''}`,'event-replan');setStatus('Pausiert','');updateButtons({running:true,paused:true})}
1269:       else if(ev.msg==='running'){appendLog('▶ Fortgesetzt','event-replan');setStatus('Läuft…','running');updateButtons({running:true,paused:false})}
1270:       break;
1271:     case 'plan_loaded':
1272:       refreshPlan();loadPlans();break;
1273:   }
1274: }
1275: 
1276: planBtn.onclick=createPlan;
1277: runBtn.onclick=()=>doAction('run');
1278: pauseBtn.onclick=()=>doAction('pause');
1279: resumeBtn.onclick=()=>doAction('resume');
1280: stopBtn.onclick=()=>doAction('stop');
1281: $('goal-input').addEventListener('keydown',e=>{if(e.key==='Enter')createPlan()});
1282: 
1283: connectWS();
1284: refreshPlan();
1285: loadPlans();
1286: </script>
