525:     // ===== NEXUS CLAW – Neon Cyber Theme: Interaktionslogik =====
526: 
527:     // ===== Lucide Icons initialisieren =====
528:     lucide.createIcons();
529: 
530:     // ===== Themenwechsel =====
531:     const darkModeBtn = document.getElementById('dark-mode');
532:     const lightModeBtn = document.getElementById('light-mode');
533:     const htmlElement = document.documentElement;
534: 
535:     function setTheme(theme) {
536:       htmlElement.setAttribute('data-theme', theme);
537:       localStorage.setItem('nexus-theme', theme);
538:       if (theme === 'dark') {
539:         darkModeBtn.classList.add('active');
540:         lightModeBtn.classList.remove('active');
541:       } else {
542:         lightModeBtn.classList.add('active');
543:         darkModeBtn.classList.remove('active');
544:       }
545:     }
546: 
547:     // Gespeichertes Thema laden
548:     const savedTheme = localStorage.getItem('nexus-theme') || 'dark';
549:     setTheme(savedTheme);
550: 
551:     darkModeBtn.addEventListener('click', () => setTheme('dark'));
552:     lightModeBtn.addEventListener('click', () => setTheme('light'));
553: 
554:     // ===== Chat-Logik =====
555:     const userInput = document.getElementById('user-input');
556:     const sendButton = document.getElementById('send-button');
557:     const messagesContainer = document.getElementById('messages');
558:     const statusIndicator = document.getElementById('status');
559: 
560:     // Senden-Button je nach Eingabe aktivieren
561:     userInput.addEventListener('input', () => {
562:       sendButton.disabled = userInput.value.trim() === '';
563:     });
564: 
565:     // Hilfsfunktion: Zeitstempel
566:     function getTime() {
567:       return new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
568:     }
569: 
570:     // Hilfsfunktion: Agenten-Icons
571:     function getAgentIcon(agent) {
572:       const agentIcons = {
573:         'code': 'code',
574:         'recherche': 'search',
575:         'kreativ': 'sparkles',
576:         'analyse': 'bar-chart-3',
577:         'system': 'cpu'
578:       };
579:       return agentIcons[agent] || 'bot';
580:     }
581: 
582:     // Nachricht hinzufügen
583:     function addMessage(content, isUser = false, agent = null, protokoll = null, actions = null) {
584:       const messageDiv = document.createElement('div');
585:       messageDiv.classList.add('message', isUser ? 'user-message' : 'nexus-message');
586: 
587:       let html = '';
588: 
589:       if (!isUser && agent) {
590:         html += '<div class="agent-info"><i data-lucide="' + (agent.icon || getAgentIcon(agent.name)) + '"></i><span>NEXUS: ' + agent.name + '</span></div>';
591:       }
592: 
593:       html += '<div class="message-content">' + content + '</div>';
594: 
595:       if (!isUser && actions) {
596:         html += '<div class="message-actions">' + actions.map(a => '<button class="action-button">' + a.text + '</button>').join('') + '</div>';
597:       }
598: 
599:       html += '<div class="message-meta"><span>' + (isUser ? 'Du' : 'NEXUS') + '</span><span>' + getTime() + '</span></div>';
600: 
601:       if (!isUser && protokoll) {
602:         html += '<div class="protokoll"><details><summary>[PROTOKOLL] ✅ Ausführung abgeschlossen</summary><ul>' + protokoll.map(item => '<li>' + item + '</li>').join('') + '</ul></details></div>';
603:       }
604: 
605:       messageDiv.innerHTML = html;
606:       messagesContainer.appendChild(messageDiv);
607:       messageDiv.scrollIntoView({ behavior: 'smooth' });
608:       lucide.createIcons();
609: 
610:       // Aktions-Buttons verknüpfen
611:       if (!isUser && actions) {
612:         messageDiv.querySelectorAll('.action-button').forEach((btn, i) => {
613:           btn.addEventListener('click', () => actions[i].callback());
614:         });
615:       }
616:     }
617: 
618:     // Status setzen
619:     function setStatus(text) {
620:       statusIndicator.textContent = text;
621:     }
622: 
623:     // ===== Echte KI-Integration =====
624:     // Trage hier die URL deines NEXUS-Backends ein:
625:     const NEXUS_API_URL = 'https://dein-nexus-backend.com/api/chat';
626:     const NEXUS_API_KEY = 'DEIN_API_KEY';
627: 
628:     async function sendMessage() {
629:       const message = userInput.value.trim();
630:       if (!message) return;
631: 
632:       addMessage(message, true);
633:       userInput.value = '';
634:       sendButton.disabled = true;
635:       setStatus('🤖 NEXUS denkt nach...');
636: 
637:       try {
638:         const response = await fetch(NEXUS_API_URL, {
639:           method: 'POST',
640:           headers: {
641:             'Content-Type': 'application/json',
642:             'Authorization': 'Bearer ' + NEXUS_API_KEY
643:           },
644:           body: JSON.stringify({ message: message, agent: 'auto' })
645:         });
646: 
647:         if (!response.ok) throw new Error('API-Fehler: ' + response.status);
648: 
649:         const data = await response.json();
650: 
651:         addMessage(
652:           data.response,
653:           false,
654:           { name: data.agent || 'NEXUS' },
655:           data.protokoll || null,
656:           data.actions || null
657:         );
658:         setStatus('🤖 NEXUS bereit');
659: 
660:       } catch (error) {
661:         // Fallback: Demo-Antwort, wenn kein Backend erreichbar ist
662:         addMessage(
663:           '⚠️ <strong>Hinweis:</strong> Kein Backend erreichbar (' + error.message + '). Hier eine <em>Demo-Antwort</em>:<br><br>Ich habe deine Anfrage empfangen. Verbinde mich mit deinem NEXUS-Backend, um echte Antworten zu erhalten. 🔧',
664:           false,
665:           { name: 'System', icon: 'cpu' },
666:           [
667:             'Modell: Demo-Modus',
668:             'Agent: System-Agent',
669:             'Status: Kein Backend verbunden'
670:           ]
671:         );
672:         setStatus('🤖 NEXUS bereit (Demo-Modus)');
673:       }
674:     }
675: 
676:     // ===== Events =====
677:     sendButton.addEventListener('click', sendMessage);
678:     userInput.addEventListener('keypress', (e) => {
679:       if (e.key === 'Enter' && !e.shiftKey) {
680:         e.preventDefault();
681:         sendMessage();
682:       }
683:     });
684: 
685:     // ===== Willkommensnachricht =====
686:     addMessage(
687:       'Willkommen bei <strong>NEXUS CLAW</strong>! 🚀<br>Ich bin NEXUS, deine zentrale KI. Frag mich alles – ich wähle automatisch das passende Modell, den Agenten und die Werkzeuge.<br><br><em>Motto: "Schnell. Klar. Sicher."</em>',
688:       false,
689:       { name: 'System', icon: 'cpu' },
690:       [
691:         'Systemstart: OK',
692:         'Theme: Neon Cyber (Dark/Light)',
693:         'Berechtigungen: minimal',
694:         'Sandbox: aktiv'
695:       ]
696:     );
