1174:   function formatMessage(text) {
1175:     let safe = esc(text);
1176:     const blocks = [];
1177:     safe = safe.replace(/```(\w*)\n?([\s\S]*?)```/g, (_, lang, code) => {
1178:       const idx = blocks.length;
1179:       blocks.push(`<pre><code>${code.replace(/\n$/, "")}</code></pre>`);
1180:       return `\u0000BLOCK${idx}\u0000`;
1181:     });
1182:     safe = safe.replace(/`([^`\n]+)`/g, "<code>$1</code>");
1183:     safe = safe.replace(/\u0000BLOCK(\d+)\u0000/g, (_, i) => blocks[Number(i)]);
1184:     return safe.replace(/\n/g, "<br />");
1185:   }
