529:   function loopStep(phase, i, loop) {
530:     const phaseIndex = Math.min(LOOP_PHASES.length - 1, Math.floor((loop.progress / 100) * LOOP_PHASES.length));
531:     const done = i < phaseIndex || loop.progress >= 100;
532:     const active = i === phaseIndex && loop.running && !loop.paused && loop.progress < 100;
533:     return `<div class="loop-step ${done ? "done" : active ? "active" : ""}">
534:       <span class="bullet">${done ? icon("check") : ""}</span>
535:       <span>${esc(phase)}</span>
536:       <span class="step-time">${done ? "✓" : active ? "läuft" : "–"}</span>
537:     </div>`;
538:   }
