1913:   function runTerminalCommand(raw) {
1914:     const cmd = String(raw || "").trim();
1915:     if (!cmd) return;
1916:     pushTerm("cmd", cmd);
1917:     const [base, ...args] = cmd.split(/\s+/);
1918:     const command = base.toLowerCase();
1919:     if (command === "clear") {
1920:       state.terminal = [];
1921:       save();
1922:       renderRoute();
1923:       return;
1924:     }
1925:     if (command === "help") {
1926:       pushTerm("ok", "Verfügbare Befehle:");
1927:       terminalHelp().forEach((h) => pushTerm("dim", `  ${h.cmd.padEnd(18)} ${h.desc}`));
1928:     } else if (command === "ls" || command === "dir") {
1929:       pushTerm("ok", "NEXUS_V7/   Unity_Game/   KI_Modelle/   Horus_Tools/   Experimente/");
1930:       pushTerm("dim", "app.py  agent_orchestrator.py  loop_engine.py  README.md  requirements.txt");
1931:     } else if (command === "pwd") {
1932:       pushTerm("ok", "/home/nexus/NEXUS_V7");
1933:     } else if (command === "whoami") {
1934:       pushTerm("ok", "nexus");
1935:     } else if (command === "date") {
1936:       pushTerm("ok", new Date().toLocaleString("de-DE"));
1937:     } else if (command === "uptime") {
1938:       pushTerm("ok", `up 4 hours, 12 minutes · load average: 0.18, 0.11, 0.07`);
1939:     } else if (command === "neofetch") {
1940:       pushTerm("sys", "       NEXUS // HORUS LINUX");
1941:       pushTerm("dim", "  OS:       Horus Linux 7.4 (proot)");
1942:       pushTerm("dim", "  Shell:    bash 5.2 (simuliert)");
1943:       pushTerm("dim", "  Host:     Android / Termux");
1944:       pushTerm("dim", "  Model:    qwen2.5-coder:1.5b");
1945:       pushTerm("dim", "  Agents:   8 Profile · 0 autonome Prozesse");
1946:     } else if (command === "status") {
1947:       pushTerm("sys", "SYSTEM STATUS");
1948:       pushTerm("ok", `  Frontend:  bereit`);
1949:       pushTerm("ok", `  Loop:      ${state.loop.running ? (state.loop.paused ? "pausiert" : "läuft") : "bereit"} · Zyklus ${state.loop.cycle}/${state.loop.total} · ${Math.round(state.loop.progress)}%`);
1950:       pushTerm(state.connection.status === "ok" ? "ok" : "warn", `  Ollama:    ${state.connection.status === "ok" ? "verbunden" : "Demo-Modus"} · ${state.settings.ollamaUrl}`);
1951:       pushTerm("dim", `  Aufgaben:  ${state.tasks.filter((t) => t.status !== "erledigt").length} offen`);
1952:     } else if (command === "ollama") {
1953:       if ((args[0] || "").toLowerCase() === "list") {
1954:         pushTerm("sys", "NAME                        ID              SIZE      MODIFIED");
1955:         pushTerm("ok", "qwen2.5-coder:1.5b          a1b2c3d4     1.0 GB    2 days ago");
1956:         pushTerm("ok", "deepseek-r1:1.5b            4d3e2f1a     1.1 GB    3 days ago");
1957:         pushTerm("ok", "llama3:8b                   e5f6a7b8     4.7 GB    5 days ago");
1958:         pushTerm("dim", "Hinweis: simulierte Ausgabe.");
1959:       } else if ((args[0] || "").toLowerCase() === "ps") {
1960:         pushTerm("warn", "Kein laufendes Modell · Simulation.");
1961:       } else {
1962:         pushTerm("warn", "Verwendung: ollama list | ollama ps");
1963:       }
1964:     } else if (command === "python" || command === "flask") {
1965:       if (cmd.includes("server.py") || cmd.includes("app.py")) {
1966:         pushTerm("sys", " * Serving Flask app 'server'");
1967:         pushTerm("sys", " * Running on http://127.0.0.1:5000");
1968:         pushTerm("warn", "SIMULATION: Es wird kein Prozess gestartet.");
1969:         addAudit("system", "Simulierter Serverstart im Terminal", "terminal");
1970:       } else {
1971:         pushTerm("dim", "Python 3.12.3 (simuliert)");
1972:       }
1973:     } else if (command === "cat") {
1974:       if ((args[0] || "").toLowerCase() === "readme.md") {
1975:         pushTerm("ok", "# NEXUS CLAW V7.4.1");
1976:         pushTerm("dim", "Hybrid AI Office · lokale Verarbeitung bevorzugen.");
1977:         pushTerm("dim", "Dashboard-Prototyp ohne autonome Codeausführung.");
1978:       } else {
1979:         pushTerm("err", `cat: ${args[0] || "Datei"}: Datei nicht lesbar (Read-Only-Prototyp)`);
1980:       }
1981:     } else if (command === "open") {
1982:       const target = (args[0] || "").replace("#/", "");
1983:       if (ROUTES[target]) {
1984:         pushTerm("ok", `Öffne ${ROUTES[target].title}…`);
1985:         save();
1986:         navigate(target);
1987:         return;
1988:       }
1989:       pushTerm("err", "Unbekannter Bereich. Nutze help oder open home.");
1990:     } else if (command === "echo") {
1991:       pushTerm("ok", args.join(" "));
1992:     } else if (command === "sudo") {
1993:       pushTerm("err", "sudo ist im Prototyp deaktiviert. Keine Codeausführung.");
1994:     } else {
1995:       pushTerm("err", `${base}: Befehl nicht gefunden (Simulation). Tippe "help".`);
1996:     }
1997:     save();
1998:     renderRoute();
1999:   }
