1180:   function formatMessage(text) {
1181:     let safe = esc(text);
1182:     const blocks = [];
1183:     safe = safe.replace(/```(\w*)\n?([\s\S]*?)```/g, (_, lang, code) => {
1184:       const idx = blocks.length;
1185:       blocks.push(`<pre><code>${code.replace(/\n$/, "")}</code></pre>`);
1186:       return `\u0000BLOCK${idx}\u0000`;
1187:     });
1188:     safe = safe.replace(/`([^`\n]+)`/g, "<code>$1</code>");
1189:     safe = safe.replace(/\u0000BLOCK(\d+)\u0000/g, (_, i) => blocks[Number(i)]);
1190:     return safe.replace(/\n/g, "<br />");
1191:   }
